    """Токены запроса; слово вне словаря каталога заменяется ближайшим словом каталога с весом FUZZY."""
    ws = words(query)
    ws = [t for t in ws if t not in STOP] or ws
    out, weight = [], {}
    for w in ws:
        st = PORTER.stem(w)
        if st in index.idf:
            out.append(st)
            weight[st] = 1.0
        elif FUZZY:
            fixed = cat.correct(w)
            st2 = PORTER.stem(fixed) if fixed else None
            if st2 in index.idf:
                out.append(st2)
                weight[st2] = max(weight.get(st2, 0.0), FUZZY)
        else:
            out.append(st)
            weight[st] = 1.0
    return out, weight


def solve(task: dict) -> str:
    catalog = [json.loads(line) for line in (Path(task["assets_dir"]) / "catalog.jsonl").open(encoding="utf-8")]
    index = BM25([tokenize(c["name"] + " " + c["description"]) for c in catalog])
    cat = Catalog(catalog)
    qt, weight = query_terms(task["input"], index, cat)
    scores = index.scores(qt, weight)
    if NGRAM:
        top = max(scores) or 1.0
        scores = [s / top + NGRAM * c for s, c in zip(scores, cat.cosine(task["input"]))]
    # при равенстве — порядок каталога, чтобы ответ был детерминированным
    ranked = sorted(range(len(catalog)), key=lambda i: (-scores[i], i))
    return json.dumps([catalog[i]["id"] for i in ranked[:TOP]])


if __name__ == "__main__":
    print(json.dumps({"answer": solve(json.load(sys.stdin))}))
